#include <limits.h>

struct Big {
    unsigned char *d; /* least-significant digit first */
    size_t len;
    size_t cap;
};

static void grow(struct Big *x, size_t needed)
{
    if (x->cap < needed) {
        size_t cap = x->cap ? x->cap : 1;
        while (cap < needed) cap *= 2;
        x->d = (unsigned char *)realloc(x->d, cap);
        if (!x->d) exit(EXIT_FAILURE);
        x->cap = cap;
    }
}

static void add(struct Big *out, const struct Big *x, const struct Big *y)
{
    size_t n = x->len > y->len ? x->len : y->len;
    grow(out, n + 1);
    unsigned carry = 0;
    for (size_t i = 0; i < n || carry; ++i) {
        unsigned v = carry;
        if (i < x->len) v += x->d[i];
        if (i < y->len) v += y->d[i];
        out->d[i] = (unsigned char)(v % 10);
        carry = v / 10;
        if (i + 1 > out->len) out->len = i + 1;
    }
    if (out->len < n) out->len = n;
}

int main(int argc, char **argv)
{
    if (argc != 2) return EXIT_FAILURE;
